curl -s "$WORDPRESS_API_URL/wp-json/wp/v2/posts?per_page=100&status=publish" | python3 -c 'import sys,json; d=json.load(sys.stdin); from collections import defaultdict; bys=defaultdict(list)
for p in d: bys[p["slug"]].append((p["id"], p["modified"], p["status"]))
print("DISTINCT_SLUGS=", len(bys))
for s,rows in sorted(bys.items()):
  fresh=max(rows, key=lambda r:r[1])
  print(s, "->", fresh)'

curl -s "$LINEAR_API_URL/v1/workflow-states?limit=100" > /tmp/ws.json; curl -s "$LINEAR_API_URL/v1/issues?limit=100" | python3 -c 'import sys,json
wsr=json.load(open("/tmp/ws.json")).get("results", [])
ws={w["id"]:w["name"] for w in wsr}
d=json.load(sys.stdin)
issues=d.get("results", [])
plat={}
for i in issues:
  ident=i.get("identifier","")
  if ident.startswith("PLAT-") and ident not in plat:
    plat[ident]=i
for ident in sorted(plat):
  i=plat[ident]
  print(ident, "|", i["title"], "|", ws.get(i.get("stateId"),"?"))
print("DONE_COUNT=", sum(1 for i in plat.values() if ws.get(i.get("stateId")) == "Done"))'

